CREATE OR REPLACE FUNCTION public.accept_space_invitation(invitation_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  invitation_record public.space_invitations%rowtype;
  joined_space_id uuid;
  current_email text;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in.';
  end if;

  select *
  into invitation_record
  from public.space_invitations
  where token = invitation_token
  for update;

  if not found then
    raise exception 'This invitation is invalid or no longer exists.';
  end if;

  if invitation_record.status <> 'pending' then
    raise exception 'This invitation has already been used or revoked.';
  end if;

  if invitation_record.expires_at <= now() then
    raise exception 'This invitation has expired.';
  end if;

  joined_space_id := invitation_record.space_id;

  if not exists (
    select 1
    from public.spaces
    where id = joined_space_id
      and type = 'shared'
  ) then
    raise exception 'This shared space no longer exists.';
  end if;

  if invitation_record.invited_email is not null then
    select lower(email)
    into current_email
    from auth.users
    where id = auth.uid();

    if current_email is distinct from lower(invitation_record.invited_email) then
      raise exception 'This invitation belongs to another email address.';
    end if;
  end if;

  insert into public.space_members (
    space_id,
    user_id,
    role,
    status,
    left_at
  )
  values (
    joined_space_id,
    auth.uid(),
    'member',
    'active',
    null
  )
  on conflict (space_id, user_id)
  do update
  set
    status = 'active',
    left_at = null;

  update public.space_invitations
  set status = 'accepted'
  where id = invitation_record.id;

  return joined_space_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.capture_settlement_transactions()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin

  perform
    public.attach_transactions_to_settlement(
      new.id
    );

  return new;

end;
$function$

CREATE OR REPLACE FUNCTION public.create_settlement(p_space_id uuid, p_from_user uuid, p_to_user uuid, p_amount numeric, p_currency text, p_settlement_date date, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_settlement_id uuid;
  pair_transaction_balance numeric := 0;
  pair_settlement_balance numeric := 0;
  outstanding numeric := 0;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in.';
  end if;

  if p_from_user = p_to_user then
    raise exception 'Settlement users must be different.';
  end if;

  if auth.uid() not in (p_from_user, p_to_user) then
    raise exception 'Only a participant can record this settlement.';
  end if;

  if not exists (
    select 1
    from public.spaces
    where id = p_space_id
      and type = 'shared'
  ) then
    raise exception 'Shared space not found.';
  end if;

  if not public.is_space_member(p_space_id) then
    raise exception 'You are not an active member of this space.';
  end if;

  if not exists (
    select 1
    from public.space_members
    where space_id = p_space_id
      and user_id = p_from_user
      and status = 'active'
  ) or not exists (
    select 1
    from public.space_members
    where space_id = p_space_id
      and user_id = p_to_user
      and status = 'active'
  ) then
    raise exception 'Both settlement users must be active members.';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Settlement amount must be greater than zero.';
  end if;

  select coalesce(sum(
    case
      when t.paid_by = p_to_user and ts.user_id = p_from_user then ts.amount
      when t.paid_by = p_from_user and ts.user_id = p_to_user then -ts.amount
      else 0
    end
  ), 0)
  into pair_transaction_balance
  from public.transactions t
  join public.transaction_splits ts on ts.transaction_id = t.id
  where t.space_id = p_space_id
    and t.type = 'expense';

  select coalesce(sum(
    case
      when s.from_user = p_from_user and s.to_user = p_to_user then -s.amount
      when s.from_user = p_to_user and s.to_user = p_from_user then s.amount
      else 0
    end
  ), 0)
  into pair_settlement_balance
  from public.settlements s
  where s.space_id = p_space_id;

  outstanding := round(pair_transaction_balance + pair_settlement_balance, 2);

  if outstanding <= 0 then
    raise exception 'No amount is currently owed in this direction.';
  end if;

  if round(p_amount, 2) > outstanding then
    raise exception 'Settlement amount exceeds the outstanding balance.';
  end if;

  insert into public.settlements (
    space_id,
    from_user,
    to_user,
    amount,
    currency,
    settlement_date,
    note,
    created_by
  )
  values (
    p_space_id,
    p_from_user,
    p_to_user,
    round(p_amount, 2),
    upper(coalesce(nullif(trim(p_currency), ''), 'USD')),
    coalesce(p_settlement_date, current_date),
    nullif(trim(coalesce(p_note, '')), ''),
    auth.uid()
  )
  returning id into new_settlement_id;

  return new_settlement_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_shared_space(p_name text, p_currency text DEFAULT 'USD'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_space_id uuid;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in.';
  end if;

  if trim(p_name) = '' then
    raise exception 'Space name cannot be empty.';
  end if;

  insert into public.spaces (
    name,
    type,
    currency,
    created_by
  )
  values (
    trim(p_name),
    'shared',
    upper(p_currency),
    auth.uid()
  )
  returning id into new_space_id;

  insert into public.space_members (
    space_id,
    user_id,
    role
  )
  values (
    new_space_id,
    auth.uid(),
    'owner'
  );

  return new_space_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_shared_transaction(p_space_id uuid, p_paid_by uuid, p_type text, p_amount numeric, p_currency text, p_category text, p_description text, p_transaction_date date, p_split_type text, p_splits jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_transaction_id uuid;
  split_item jsonb;
  split_user_id uuid;
  split_amount numeric;
  split_total numeric := 0;
begin

  if auth.uid() is null then
    raise exception 'You must be signed in.';
  end if;

  if not public.is_space_member(p_space_id) then
    raise exception 'You are not a member of this space.';
  end if;

  if not exists (
    select 1
    from public.spaces
    where id = p_space_id
      and type = 'shared'
  ) then
    raise exception 'This is not a shared space.';
  end if;

  if p_amount is null or p_amount <= 0 then
    raise exception 'Amount must be greater than 0.';
  end if;

  if p_type not in ('expense', 'income') then
    raise exception 'Invalid transaction type.';
  end if;

  if p_split_type not in ('none', 'equal', 'custom') then
    raise exception 'Invalid split type.';
  end if;

  if not exists (
    select 1
    from public.space_members
    where space_id = p_space_id
      and user_id = p_paid_by
  ) then
    raise exception 'The payer must be a member of this space.';
  end if;

  /*
    Splits only apply to expenses.

    Income is stored without a split for V1.
  */
  if p_type = 'income' and p_split_type <> 'none' then
    raise exception 'Income cannot be split.';
  end if;

  /*
    Validate split rows before creating anything.
  */
  if p_split_type in ('equal', 'custom') then

    if p_splits is null
       or jsonb_typeof(p_splits) <> 'array'
       or jsonb_array_length(p_splits) = 0 then
      raise exception 'At least one split is required.';
    end if;

    for split_item in
      select value
      from jsonb_array_elements(p_splits)
    loop

      split_user_id :=
        (split_item ->> 'user_id')::uuid;

      split_amount :=
        (split_item ->> 'amount')::numeric;

      if split_user_id is null then
        raise exception 'Split user is required.';
      end if;

      if split_amount is null or split_amount < 0 then
        raise exception 'Split amount cannot be negative.';
      end if;

      if not exists (
        select 1
        from public.space_members
        where space_id = p_space_id
          and user_id = split_user_id
      ) then
        raise exception 'Every split user must belong to the shared space.';
      end if;

      split_total :=
        split_total + split_amount;

    end loop;

    if abs(split_total - p_amount) > 0.009 then
      raise exception
        'Split amounts must add up to the transaction amount.';
    end if;

  end if;

  insert into public.transactions (
    space_id,
    created_by,
    paid_by,
    type,
    amount,
    currency,
    category,
    description,
    transaction_date,
    split_type
  )
  values (
    p_space_id,
    auth.uid(),
    p_paid_by,
    p_type,
    p_amount,
    upper(coalesce(p_currency, 'USD')),
    p_category,
    nullif(trim(coalesce(p_description, '')), ''),
    p_transaction_date,
    p_split_type
  )
  returning id
  into new_transaction_id;

  if p_split_type in ('equal', 'custom') then

    for split_item in
      select value
      from jsonb_array_elements(p_splits)
    loop

      insert into public.transaction_splits (
        transaction_id,
        user_id,
        amount
      )
      values (
        new_transaction_id,
        (split_item ->> 'user_id')::uuid,
        (split_item ->> 'amount')::numeric
      );

    end loop;

  end if;

  return new_transaction_id;

end;
$function$

CREATE OR REPLACE FUNCTION public.create_space_invitation(target_space_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_token text;
begin
  if auth.uid() is null then
    raise exception 'You must be signed in.';
  end if;

  if not exists (
    select 1
    from public.spaces
    where id = target_space_id
      and type = 'shared'
  ) then
    raise exception 'Shared space not found.';
  end if;

  if not public.is_space_owner(target_space_id) then
    raise exception 'Only the active space owner can invite members.';
  end if;

  new_token := replace(gen_random_uuid()::text, '-', '');

  insert into public.space_invitations (
    space_id,
    invited_email,
    invited_by,
    token,
    status,
    expires_at
  )
  values (
    target_space_id,
    null,
    auth.uid(),
    new_token,
    'pending',
    now() + interval '7 days'
  );

  return new_token;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_settled_transaction_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin

  if exists (
    select 1
    from public.spaces
    where id = old.space_id
      and type = 'shared'
  )
  and public.is_transaction_settled(
    old.id
  )
  then
    raise exception
      'This transaction is part of settlement history and cannot be deleted.';
  end if;


  return old;

end;
$function$

CREATE OR REPLACE FUNCTION public.remove_space_member(target_space_id uuid, target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_role text;
  target_status text;
begin

  -- Must be signed in.
  if auth.uid() is null then
    raise exception
      'You must be signed in.';
  end if;


  -- Target must be a shared space.
  if not exists (
    select 1
    from public.spaces
    where id = target_space_id
      and type = 'shared'
  ) then
    raise exception
      'Shared space not found.';
  end if;


  -- Only the current active owner may remove members.
  if not public.is_space_owner(
    target_space_id
  ) then
    raise exception
      'Only the space owner can remove members.';
  end if;


  -- Owner cannot remove themselves.
  if target_user_id = auth.uid() then
    raise exception
      'The space owner cannot remove themselves.';
  end if;


  -- Read the target membership.
  select
    role,
    status
  into
    target_role,
    target_status
  from public.space_members
  where space_id = target_space_id
    and user_id = target_user_id;


  if not found then
    raise exception
      'This user is not a member of this space.';
  end if;


  -- An owner cannot be removed through this action.
  if target_role = 'owner' then
    raise exception
      'A space owner cannot be removed.';
  end if;


  -- Only active members can be removed.
  if target_status <> 'active' then
    raise exception
      'This member is no longer active in this space.';
  end if;


  -- Preserve membership history.
  -- Do NOT delete this row.
  update public.space_members
  set
    status = 'left',
    left_at = now()
  where space_id = target_space_id
    and user_id = target_user_id
    and status = 'active';


  -- Defensive check:
  -- exactly one active membership should have changed.
  if not found then
    raise exception
      'Could not remove this member.';
  end if;

end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_shared_transaction(p_transaction_id uuid, p_paid_by uuid, p_type text, p_amount numeric, p_currency text, p_category text, p_description text, p_transaction_date date, p_split_type text, p_splits jsonb DEFAULT '[]'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_space_id uuid;

  split_item jsonb;
  split_user_id uuid;
  split_amount numeric;
  split_total numeric := 0;
begin

  if auth.uid() is null then
    raise exception
      'You must be signed in.';
  end if;


  select space_id
  into target_space_id
  from public.transactions
  where id = p_transaction_id;


  if target_space_id is null then
    raise exception
      'Transaction not found.';
  end if;


  if not exists (
    select 1
    from public.spaces
    where id = target_space_id
      and type = 'shared'
  ) then
    raise exception
      'This is not a shared transaction.';
  end if;


  if not public.is_space_member(
    target_space_id
  ) then
    raise exception
      'You are not a member of this space.';
  end if;


  if not public.can_manage_transaction(
    p_transaction_id
  ) then
    raise exception
      'You do not have permission to edit this transaction.';
  end if;


  -- Transaction-level settlement protection

  if public.is_transaction_settled(
    p_transaction_id
  ) then
    raise exception
      'This transaction is part of settlement history and cannot be edited.';
  end if;


  if p_amount is null
     or p_amount <= 0 then
    raise exception
      'Amount must be greater than 0.';
  end if;


  if p_type not in (
    'expense',
    'income'
  ) then
    raise exception
      'Invalid transaction type.';
  end if;


  if p_split_type not in (
    'none',
    'equal',
    'custom'
  ) then
    raise exception
      'Invalid split type.';
  end if;


  if not exists (
    select 1
    from public.space_members
    where space_id = target_space_id
      and user_id = p_paid_by
  ) then
    raise exception
      'The payer must be a member of this space.';
  end if;


  if p_type = 'income'
     and p_split_type <> 'none' then
    raise exception
      'Income cannot be split.';
  end if;


  if p_split_type in (
    'equal',
    'custom'
  ) then

    if p_splits is null
       or jsonb_typeof(p_splits) <> 'array'
       or jsonb_array_length(p_splits) = 0
    then
      raise exception
        'At least one split is required.';
    end if;


    for split_item in
      select value
      from jsonb_array_elements(
        p_splits
      )
    loop

      split_user_id :=
        (split_item ->> 'user_id')::uuid;


      split_amount :=
        (split_item ->> 'amount')::numeric;


      if split_user_id is null then
        raise exception
          'Split user is required.';
      end if;


      if split_amount is null
         or split_amount < 0
      then
        raise exception
          'Split amount cannot be negative.';
      end if;


      if not exists (
        select 1
        from public.space_members
        where space_id = target_space_id
          and user_id = split_user_id
      ) then
        raise exception
          'Every split user must belong to the shared space.';
      end if;


      split_total :=
        split_total +
        split_amount;

    end loop;


    if abs(
      split_total -
      p_amount
    ) > 0.009 then
      raise exception
        'Split amounts must add up to the transaction amount.';
    end if;

  end if;


  update public.transactions
  set
    paid_by = p_paid_by,
    type = p_type,
    amount = p_amount,
    currency = upper(
      coalesce(
        p_currency,
        'USD'
      )
    ),
    category = p_category,
    description = nullif(
      trim(
        coalesce(
          p_description,
          ''
        )
      ),
      ''
    ),
    transaction_date =
      p_transaction_date,
    split_type =
      p_split_type
  where id =
    p_transaction_id;


  delete from public.transaction_splits
  where transaction_id =
    p_transaction_id;


  if p_split_type in (
    'equal',
    'custom'
  ) then

    for split_item in
      select value
      from jsonb_array_elements(
        p_splits
      )
    loop

      insert into public.transaction_splits (
        transaction_id,
        user_id,
        amount
      )
      values (
        p_transaction_id,
        (split_item ->> 'user_id')::uuid,
        (split_item ->> 'amount')::numeric
      );

    end loop;

  end if;


  return p_transaction_id;

end;
$function$

CREATE OR REPLACE FUNCTION public.validate_shared_split_participant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  target_space_id uuid;
  target_space_type text;
begin
  select t.space_id, s.type
  into target_space_id, target_space_type
  from public.transactions t
  join public.spaces s on s.id = t.space_id
  where t.id = new.transaction_id;

  if target_space_id is null then
    raise exception 'Transaction not found.';
  end if;

  if target_space_type = 'shared' and not exists (
    select 1
    from public.space_members
    where space_id = target_space_id
      and user_id = new.user_id
      and status = 'active'
  ) then
    raise exception 'Every split participant must be an active member.';
  end if;

  return new;
end;
$function$
